// The benchmark's headline, frozen out of a comparison run for the hosted site.
//
//   BENCH_TOOLS=… node --experimental-strip-types bench/compare/leaderboard.ts --run v7
//
// The hosted /labs/bench has no run data (results.json is hundreds of KB of numbers about
// art that is not all redistributable), so its Overview reads small generated files.
// This writes src/components/labs/bench/leaderboard.generated.ts: per HELD-OUT corpus, the
// mean-rank leaderboard (benchData.ts leaderboard(): ranks, bootstrap CI, Friedman,
// Nemenyi CD, Pareto shares, per-metric breakdown) in the headline view and in the ablation
// view. Nothing is computed here that report.ts does not compute the same way: both call
// the one pure function, so the page and summary.md cannot disagree.
//
// In-sample corpora are left out on purpose: LogoLab was developed against them, and a
// leaderboard is exactly the kind of number that gets quoted without its footnote.

import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { REPO, RESULTS } from './paths.ts'
import {
  headlineCorpora,
  leaderboard,
  type BenchResults,
  type Leaderboard,
} from '../../src/components/labs/bench/benchData.ts'
import type { LeaderboardFile } from '../../src/components/labs/bench/leaderboardTypes.ts'

const argv = process.argv.slice(2)
const RUN = argv.includes('--run') ? argv[argv.indexOf('--run') + 1] : 'v7'
const OUT = join(REPO, 'src', 'components', 'labs', 'bench', 'leaderboard.generated.ts')

/** Five significant digits, so the file is small and diffs are about results, not float
 *  noise. Significant, not decimal places: a p-value of 1e-40 rounded to 4 places is 0. */
function round(v: unknown): unknown {
  if (typeof v === 'number') return Number.isFinite(v) ? Number(v.toPrecision(5)) : null
  if (Array.isArray(v)) return v.map(round)
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, round(x)]))
  return v
}

const data = JSON.parse(readFileSync(join(RESULTS, RUN, 'results.json'), 'utf8')) as BenchResults
const boards: Leaderboard[] = []
for (const corpus of headlineCorpora(data.rows))
  for (const view of ['headline', 'ablation'] as const) boards.push(leaderboard(data.rows, { corpus, view }))

const file: LeaderboardFile = { run: data.meta.run ?? RUN, date: data.meta.date, boards }
writeFileSync(
  OUT,
  `// Generated by bench/compare/leaderboard.ts from run ${RUN}: do not edit, re-run it.\n` +
    `import type { LeaderboardFile } from './leaderboardTypes'\n\n` +
    `export const LEADERBOARD: LeaderboardFile = ${JSON.stringify(round(file))}\n`,
)

for (const b of boards) {
  const f = b.friedman
  console.log(
    `\n${b.corpus} · ${b.view} · ${b.kind} · N=${b.n} k=${b.k} · CD.05=${b.cd05?.toFixed(3)} · ` +
      (f ? `χ²=${f.chi2.toFixed(1)} p=${f.p.toExponential(2)} F=${f.ff.toFixed(2)} pF=${f.pF.toExponential(2)}` : ''),
  )
  for (const t of b.tools)
    console.log(
      `  ${t.tool.padEnd(28)} ${t.mean.toFixed(2)} [${t.lo.toFixed(2)}, ${t.hi.toFixed(2)}] case ${t.caseMean.toFixed(2)}  ` +
        `win ${(t.pareto.win * 100).toFixed(0)}% loss ${(t.pareto.loss * 100).toFixed(0)}% inc ${(t.pareto.incomparable * 100).toFixed(0)}%  ` +
        b.metrics.map((m) => `${m.label} ${t.perMetric[m.key]?.toFixed(2) ?? '—'}`).join(' '),
    )
  for (const e of b.excluded) console.log(`  (excluded ${e.tool}: ${e.reason})`)
}
console.log(`\nwrote ${OUT}`)
